import React from 'react';

const NewsCard = ({ article }) => (
  <div className="bg-white dark:bg-gray-800 rounded-lg overflow-hidden shadow hover:shadow-lg transition-shadow">
    <img src={article.imageUrl} alt={article.title} className="w-full h-40 object-cover" />
    <div className="p-4">
      <h3 className="text-lg font-semibold mb-2">{article.title}</h3>
      <p className="text-sm text-gray-600 dark:text-gray-300">{article.description}</p>
    </div>
  </div>
);

export default NewsCard;
